#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public static class LibraryOrderBoundaryPresentationValidation
{
 public static bool Running{get;private set;}
 public static string Output{get;private set;}
 [Serializable] class Result{public string folder,status;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static IEnumerator Frame(){yield return new WaitForEndOfFrame();yield return null;Canvas.ForceUpdateCanvases();}
 static void Click(Button b){Check(b!=null,"Missing button");Canvas.ForceUpdateCanvases();var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,b.transform.TransformPoint(((RectTransform)b.transform).rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(b.interactable&&hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Ordering ray blocked "+b.name);ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,ExecuteEvents.pointerClickHandler);}
 static ForgeSeatView[] Read(string test,string kind){var rs=Directory.GetFiles(".tools/library-order-1007/native/"+test,"result.json",SearchOption.AllDirectories).Select(p=>JsonUtility.FromJson<Result>(File.ReadAllText(p))).Where(r=>r.status=="PASS").ToArray();Check(rs.Length==1,"Ambiguous producer "+test);string trace=rs[0].folder+"/trace.jsonl";if(!File.Exists(Output+"/inputs/"+test+".jsonl")){File.Copy(trace,Output+"/inputs/"+test+".jsonl");File.AppendAllText(Output+"/inputs.tsv",test+"\t"+trace+"\n");}return File.ReadLines(trace).Select(JsonUtility.FromJson<ForgeWireMessage>).Where(m=>m.type=="request"&&m.request.kind==kind).Select(m=>{Check(m.request.seat==1,"Wrong actual input recipient");var v=m.views[0];v.request=m.request;v.awaitingInput=true;return v;}).ToArray();}
 public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("LibraryOrderValidation").AddComponent<ForgeBattlefieldController>();Running=true;Output=".tools/library-order-1007/ui/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");Directory.CreateDirectory(Output+"/sources");File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(".tools/library-order-1007/ui/latest.txt",Output);foreach(string p in new[]{"Assets/Scripts/Editor/LibraryOrderBoundaryPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.CardSelection.cs"})File.Copy(p,Output+"/sources/"+Path.GetFileName(p));ui.StartCoroutine(Guard(ui));}
 static IEnumerator Guard(ForgeBattlefieldController ui){var tasks=new Stack<IEnumerator>();tasks.Push(Validate(ui));try{while(tasks.Count>0){object next;try{var t=tasks.Peek();if(!t.MoveNext()){tasks.Pop();continue;}next=t.Current;}catch(Exception e){File.WriteAllText(Output+"/result.txt","FAIL "+e);throw;}if(next is IEnumerator nested)tasks.Push(nested);else yield return next;}File.WriteAllText(Output+"/result.txt","PASS: actual five same-name library ordering and mixed graveyard ordering sequences in three languages: original individual card IDs/art, exact order numbers/count/confirm threshold, reset, panel reuse, fixed typography bounds, actual ray clicks/native indexes and stale/duplicate/readonly guards. Actual two-stage Telling Time selection in primary language. Native outcomes independent; existing consumer increment, no new UI first.");}finally{while(tasks.Count>0)(tasks.Pop() as IDisposable)?.Dispose();Running=false;}}
 static IEnumerator Order(ForgeBattlefieldController ui,string test)
 {
  var views=Read(test,"OrderCards");Check(views.Length>2,"No actual complete ordering sequence");ui.Present(null,1,false,null,null,"");GameObject panel=null;int[] fonts=null;
  for(int n=0;n<views.Length;n++){
   var v=views[n];int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};ui.Present(v,1,true,submit,null,"");yield return Frame();var current=GameObject.Find("CardSelection");Check(current!=null,"Missing ordering window");Check(panel==null||panel==current,"Ordering rebuilt stable panel");panel=current;
   var labels=panel.GetComponentsInChildren<Text>();var now=labels.Where(t=>t.name=="Title"||t.name=="Count"||t.name=="Instruction").Select(t=>t.fontSize).ToArray();Check(fonts==null||fonts.SequenceEqual(now),"Ordering font changed between requests");fonts=now;
   foreach(var t in labels.Where(t=>t.name=="Title"||t.name=="Count"||t.name=="Instruction"))Check(!t.resizeTextForBestFit&&t.preferredHeight<=t.rectTransform.rect.height+2&&!t.canvasRenderer.cull&&t.cachedTextGenerator.vertexCount>0,"Ordering header clipped "+t.name+" "+t.preferredHeight+"/"+t.rectTransform.rect.height);
   var options=v.request.options;foreach(var o in options.Where(o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name))){var art=panel.transform.Find("CardSelectionScroll/Viewport/Content/ChoiceCard_"+o.card.id+"/Artwork");if(art==null)art=panel.GetComponentsInChildren<Transform>().Single(t=>t.name=="ChoiceCard_"+o.card.id).Find("Artwork");Check(art.GetComponent<Image>().sprite!=null,"Ordering art missing");Check(art.Find("Order").GetComponent<Text>().text==(o.selected?o.order.ToString():""),"Wrong individual order number");}
   int confirm=Array.FindIndex(options,o=>o.id=="confirm-cards");Check((confirm>=0)==(v.request.selectedCount==v.request.minCount),"Wrong ordering confirm gate");
   string id;
   if(n==views.Length-1){Check(confirm>=0,"Final ordering confirm missing");id="confirm-cards";ScreenCapture.CaptureScreenshot(Output+"/"+GamePreferences.Language+"-"+test+".png");yield return new WaitForSecondsRealtime(.15f);}
   else {var next=views[n+1].request.options.Where(o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name)&&o.selected).ToArray();var selected=options.Where(o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name)&&o.selected).ToArray();if(next.Length==0&&selected.Length>0)id="reset-cards";else{var added=next.Single(o=>!selected.Any(s=>s.card.id==o.card.id));id=options.Single(o=>o.card!=null&&o.card.id==added.card.id).id;}}
   int index=Array.FindIndex(options,o=>o.id==id);Check(index>=0,"Missing actual option");ui.Choose(index,v.request.requestId-1);Check(calls==0,"Stale ordering submitted");
   Button b=id=="confirm-cards"||id=="reset-cards"?panel.GetComponentsInChildren<Button>().Single(x=>x.name=="SelectionAction_"+index):panel.GetComponentsInChildren<Transform>().Single(t=>t.name=="ChoiceCard_"+options[index].card.id).Find("Artwork").GetComponent<Button>();Click(b);Check(calls==1&&last==index,"Wrong ordering native index");ui.Choose(index,v.request.requestId);Check(calls==1,"Duplicate ordering accepted");
   if(n==views.Length-1){ui.Present(v,1,false,submit,null,"");yield return Frame();ui.Choose(index,v.request.requestId);Check(calls==1&&panel.GetComponentsInChildren<Button>().All(x=>!x.interactable),"Readonly ordering accepted");}
   File.AppendAllText(Output+"/steps.log",GamePreferences.Language+" "+test+" "+n+" "+id+" PASS\n");
  }
 }
 static IEnumerator Select(ForgeBattlefieldController ui){foreach(var v in Read("telling-three","InputSelectEntitiesFromList")){int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();var panel=GameObject.Find("CardSelection");Check(panel!=null,"No actual dual-region selector");int index=Array.FindIndex(v.request.options,o=>o.id=="ok");if(index<0)index=Array.FindIndex(v.request.options,o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name));Check(index>=0,"No actual dual-region option");var b=v.request.options[index].id=="ok"?panel.GetComponentsInChildren<Button>().Single(x=>x.name=="SelectionAction_"+index):panel.GetComponentsInChildren<Transform>().Single(t=>t.name=="ChoiceCard_"+v.request.options[index].card.id).Find("Artwork").GetComponent<Button>();Click(b);Check(calls==1&&last==index,"Dual-region selector lost native identity");File.AppendAllText(Output+"/steps.log","zh-CN telling-three request "+v.request.requestId+" PASS\n");}}
 static IEnumerator Related(ForgeBattlefieldController ui){var meta=JsonUtility.FromJson<Result>(File.ReadAllText(".tools/exert-branches-1006/native/attack-two-result.json"));Check(meta.status=="PASS","Missing original exert proof");foreach(string p in new[]{".tools/mechanic-coverage/runs/20261004T000513050100Z/library-costs/evidence/own-order-1-2.json",meta.folder+"/exert-choice-0.json",meta.folder+"/exert-choice-2.json"}){File.Copy(p,Output+"/inputs/legacy-"+Path.GetFileName(p));File.AppendAllText(Output+"/inputs.tsv","legacy\t"+p+"\n");var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));int calls=0,last=-1;ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,true,i=>{calls++;last=i;},null,"");yield return Frame();var panel=GameObject.Find("CardSelection");Check(panel!=null,"Missing related ordering consumer");foreach(var t in panel.GetComponentsInChildren<Text>().Where(t=>t.name=="Title"||t.name=="Instruction"||t.name=="Count"))Check(!t.resizeTextForBestFit&&t.preferredHeight<=t.rectTransform.rect.height+2,"Related header clipped "+t.name);bool exert=v.request.selectionPurpose=="exertAttack";Check(panel.GetComponentsInChildren<Transform>().Any(t=>t.name=="Order")==!exert,"Related consumer changed ordering purpose");int index=Array.FindIndex(v.request.options,o=>o.id=="confirm-cards");Check(index>=0,"Related native confirm absent");Click(panel.GetComponentsInChildren<Button>().Single(b=>b.name=="SelectionAction_"+index));Check(calls==1&&last==index,"Related confirmation lost index");File.AppendAllText(Output+"/steps.log","zh-CN legacy "+p+" PASS\n");}}
 static IEnumerator Validate(ForgeBattlefieldController ui){string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var migration=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldMigrationNotice>();bool me=migration!=null&&migration.enabled;if(migration!=null)migration.enabled=false;var module=EventSystem.current.currentInputModule;bool ie=module!=null&&module.enabled;if(module!=null)module.enabled=false;try{foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=language;GamePreferences.SetLanguage(language);float until=Time.realtimeSinceStartup+12;while((!GamePreferences.Ready||change&&GamePreferences.Revision==revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale not ready");yield return Order(ui,"index-five");yield return Order(ui,"fossil-grave");if(language=="zh-CN"){yield return Select(ui);yield return Related(ui);}}}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;if(migration!=null)migration.enabled=me;if(module!=null)module.enabled=ie;GamePreferences.SetLanguage(locale);}}
}
#endif
